dockerfile_steps:
RUN printf 'server {
  listen 80 default_server;
  root /var/www/yeswiki;
  index index.php wakka.php index.html;
  access_log /dev/stdout;
  error_log /dev/stderr;
  location / { try_files $uri $uri/ /index.php?$query_string; }
  location ~ [.]php$ { include snippets/fastcgi-php.conf; fastcgi_pass unix:/run/php/php8.2-fpm.sock; }
}
server {
  listen 8080;
  root /var/www/wordpress;
  index index.php;
  access_log /dev/stdout;
  error_log /dev/stderr;
  location / { try_files $uri $uri/ /index.php?$args; }
  location ~ [.]php$ { include snippets/fastcgi-php.conf; fastcgi_pass unix:/run/php/php8.2-fpm-root.sock; }
}
' > /etc/nginx/sites-available/default
